          'Nutrition': ['Healthy Eating', 'Meal Planning', 'Vitamins', 'Hydration'],
          'Movement': ['Home Workouts', 'Walking Plans', 'Flexibility', 'Recovery']
        }
      },
      tools: {
        title: 'Tools',
        groups: {
          'Calculators': ['Calorie Calculator', 'BMI Calculator', 'Macro Calculator', 'Heart Rate Zones'],
          'Medication': ['Drug Directory', 'Pill Identifier', 'Interaction Checker', 'Savings Finder'],
