          'This Week': ['Top Stories', 'Editor Picks', 'New Studies', 'Most Shared'],
          'Seasonal': ['Allergy Season', 'Summer Hydration', 'Travel Health', 'Flu Preparedness'],
          'Guides': ['Healthy Aging', 'Family Health', 'Women\'s Health', 'Men\'s Health']
        }
      },
      connect: {
        title: 'Connect',
        groups: {
          'Community': ['Discussion Boards', 'Success Stories', 'Q&A'],
          'About WellSource': ['Editorial Policy', 'Medical Review Board', 'Contact Us'],
          'Follow': ['Newsletter', 'Podcast', 'Social Channels']
        }
      }
    };

    const menuButtons = [...document.querySelectorAll('.nav-btn')];
    const megaMenu = document.getElementById('megaMenu');
    const megaTitle = document.getElementById('megaTitle');
    const megaGrid = document.getElementById('megaGrid');

    function renderMega(key) {
      const data = megaData[key];
      megaTitle.textContent = data.title;
      megaGrid.innerHTML = Object.entries(data.groups).map(([group, links]) => `
        <section class="mega-group">
          <h4>${group}</h4>
          ${links.map((link) => `<a href="index.html">${link}</a>`).join('')}
        </section>
      `).join('');
    }

    function closeMenu() {
      megaMenu.classList.remove('open');
      menuButtons.forEach((btn) => btn.setAttribute('aria-expanded', 'false'));
    }

    menuButtons.forEach((btn) => {
      btn.addEventListener('click', (event) => {
        event.stopPropagation();
        const isExpanded = btn.getAttribute('aria-expanded') === 'true';
        if (isExpanded) { closeMenu(); return; }

        menuButtons.forEach((b) => b.setAttribute('aria-expanded', 'false'));
        btn.setAttribute('aria-expanded', 'true');
        renderMega(btn.dataset.menu);
        megaMenu.classList.add('open');
      });
    });

    document.addEventListener('click', (event) => {
      const nav = document.querySelector('.main-nav');
      if (!nav.contains(event.target)) closeMenu();
    });

    const readData = {
      top: [
        ['Nutrition', '16 Superfoods That Are Worthy of the Title'],
        ['Medication', 'Does Ozempic Cause Hair Loss?'],
        ['Mental Health', 'Can Music Therapy Help with Depression?'],
