        ['Stress', 'A Therapist\'s Guide to Daily Stress Resets'],
        ['Mood', 'What a Mental Health Check-In Should Actually Include'],
        ['Sleep', 'Can Better Sleep Habits Lower Anxiety?'],
        ['Focus', 'Why Digital Boundaries Improve Emotional Health']
      ],
      reviews: [
        ['Products', 'Best Smart Scales for Home Health Tracking'],
        ['Tech', 'Wearable Sleep Trackers: Which Metrics Matter?'],
        ['Kitchen', 'Top 6 Air Fryers for Fast Healthy Meals'],
        ['Home', 'Do Standing Desks Really Help Back Pain?']
      ],
      recipes: [
        ['Breakfast', 'High-Protein Overnight Oats, 5 Ways'],
        ['Lunch', 'Mediterranean Meal Prep Bowls for Busy Weeks'],
        ['Dinner', '10 Heart-Healthy Dinners in Under 30 Minutes'],
        ['Snacks', 'No-Bake Snacks with Fiber and Healthy Fats']
      ],
      skin: [
        ['Skin Care', 'Dermatologists Explain Retinol for Beginners'],
        ['SPF', 'How to Pick a Sunscreen You\'ll Actually Use'],
        ['Acne', 'Hormonal Acne Basics: Treatments That Work'],
        ['Routine', 'Minimalist Morning Skin Routine for Sensitive Skin']
      ]
    };

    const readsGrid = document.getElementById('readsGrid');
    const tabButtons = [...document.querySelectorAll('.tab-btn')];

    function renderReads(key) {
      readsGrid.innerHTML = readData[key].map(([meta, title]) => `
        <article class="article-card">
          <div class="article-image" aria-hidden="true">WellSource</div>
          <div class="article-body">
            <div class="article-meta">${meta}</div>
            <h3 class="article-title">${title}</h3>
          </div>
        </article>
      `).join('');
    }

    tabButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        tabButtons.forEach((b) => {
          b.classList.remove('active');
          b.setAttribute('aria-selected', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');
        renderReads(btn.dataset.tab);
      });
    });

    renderReads('top');

    const topicsWrap = document.getElementById('topicsWrap');
    document.getElementById('topicsPrev').addEventListener('click', () => {
      topicsWrap.scrollBy({ left: -280, behavior: 'smooth' });
    });
    document.getElementById('topicsNext').addEventListener('click', () => {
      topicsWrap.scrollBy({ left: 280, behavior: 'smooth' });
    });

    const form = document.getElementById('newsletterForm');
    const msg = document.getElementById('formMsg');
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      const email = new FormData(form).get('email');
      msg.textContent = `Thanks, ${email}! You’re subscribed to WellSource Weekly.`;
      form.reset();
    });
  </script>
